SINA_SMART["parasito-leishmaniasis"] = {"lecture":"parasito-leishmaniasis","title":"Leishmaniasis","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"parasito-leishmaniasis:e0","text":"Leishmania: flagellate, obligate intracellular in macrophages.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"parasito-leishmaniasis:e4","text":"Notifiable in Morocco since 1995.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"parasito-leishmaniasis:e1","text":"Vector: female sandfly (Phlebotomus); painful night bite.","topic":"Parasite, vector, reservoirs, cycle","sec":1,"importance":"core","highYield":"untested"},{"id":"parasito-leishmaniasis:e2","text":"Promastigote in fly; amastigote in mammals.","topic":"Parasite, vector, reservoirs, cycle","sec":1,"importance":"core","highYield":"untested"},{"id":"parasito-leishmaniasis:e3","text":"Reservoirs: dog (L. infantum), rodents (L. major), human (L. tropica).","topic":"Parasite, vector, reservoirs, cycle","sec":1,"importance":"core","highYield":"untested"},{"id":"parasito-leishmaniasis:e5","text":"VL (L. infantum): child, fever + pallor + splenomegaly, pancytopenia, ↑ gammaglobulins.","topic":"Visceral leishmaniasis","sec":2,"importance":"core","highYield":"untested"},{"id":"parasito-leishmaniasis:e6","text":"VL diagnosis: bone marrow amastigotes; rK39; ELISA/WB.","topic":"Visceral leishmaniasis","sec":2,"importance":"core","highYield":"untested"},{"id":"parasito-leishmaniasis:e7","text":"L. tropica: urban, dry, single slow lesion. L. major: rural, wet, multiple, fast.","topic":"Cutaneous and mucocutaneous forms","sec":3,"importance":"core","highYield":"untested"},{"id":"parasito-leishmaniasis:e8","text":"Mucocutaneous (L. braziliensis): nose/palate destruction.","topic":"Cutaneous and mucocutaneous forms","sec":3,"importance":"core","highYield":"untested"},{"id":"parasito-leishmaniasis:e10","text":"VL: antimony 28 days or liposomal amphotericin B.","topic":"Treatment","sec":4,"importance":"core","highYield":"untested"},{"id":"parasito-leishmaniasis:e11","text":"Monitor ECG (QT) on antimony.","topic":"Treatment","sec":4,"importance":"core","highYield":"untested"},{"id":"parasito-leishmaniasis:e9","text":"Glucantime: intralesional (< 5 lesions, < 4 cm) or IM 20 mg/kg/d.","topic":"Treatment","sec":4,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"1iba1l0":"a","msiaoc":"a","aaq6ia":"a","ti8fxs":"a","13trzfe":"a","nxfk34":"a","1e36y4w":"a","121v35r":"a","1ihgpbx":"a","1jua02y":"a","1q7sm4e":"a","wtalfi":"a","1b0t8yg":"a","bjuawx":"a","qgn3fk":"a","1nkkjue":"a","1ryjd78":"a","mgmvow":"x"},"mapCounts":{"verified":0,"auto":17,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"parasito-leishmaniasis:e0":{"s":0,"u":["Leishmania: flagellate, obligate intracellular in macrophages.","Leishmaniases are anthropozoonoses caused by flagellate protozoa of the genus Leishmania , obligate intracellular parasites of the mononuclear phagocyte system, transmitted by the sandfly ( Phlebotomus ) ."],"dp":[]},"parasito-leishmaniasis:e4":{"s":0,"u":["Notifiable in Morocco since 1995.","Notifiable in Morocco since 1995 ; cutaneous scars carry social stigma."],"dp":[]},"parasito-leishmaniasis:e1":{"s":1,"u":["Vector: female sandfly (Phlebotomus); painful night bite.","Vector : small (2-5 mm) hairy yellowish sandfly, hunched, wings raised in a V, active at dusk and night above 19 °C, silent short flight, painful bite ; larvae in damp soil, burrows."],"dp":[]},"parasito-leishmaniasis:e2":{"s":1,"u":["Promastigote in fly; amastigote in mammals.","Dimorphic, heteroxenous: promastigote (15-25 µm, flagellated, motile) in the sandfly gut and culture; amastigote (2-6 µm, aflagellate, intracellular) in mammals; binary fission.","Cycle : the sandfly ingests infected macrophages; promastigotes multiply in its gut and move to the proboscis; at the next bite they are injected, phagocytosed by macrophages and become amastigotes."],"dp":[]},"parasito-leishmaniasis:e3":{"s":1,"u":["Reservoirs: dog (L. infantum), rodents (L. major), human (L. tropica).","Reservoirs : dog ( L. infantum ), rodents ( L. major ), humans ( L. tropica, L. donovani ).","Distribution: visceral L. infantum (Mediterranean), L. donovani (India, East Africa); cutaneous L. major (arid Maghreb), L. tropica (some foci in Morocco), L. infantum ; New World species ( L. braziliensis, mexicana, guyanensis, amazonensis )."],"dp":[]},"parasito-leishmaniasis:e5":{"s":2,"u":["VL (L. infantum): child, fever + pallor + splenomegaly, pancytopenia, ↑ gammaglobulins.","Triad: irregular fever, pallor, splenomegaly , with hepatomegaly, lymph nodes, weight loss, digestive signs, bleeding (epistaxis, gum), skin and renal involvement; fatal without treatment , good outcome if treated early.","Kala-azar ('black fever')."],"dp":[]},"parasito-leishmaniasis:e6":{"s":2,"u":["VL diagnosis: bone marrow amastigotes; rK39; ELISA/WB.","Parasitology : amastigotes on MGG in bone marrow (sternal puncture in adults, iliac crest in children) , lymph node, or blood in immunocompromised; NNN culture.","Serology : ELISA, Western blot (14 and 16 kD bands), rK39 rapid test (sensitivity > 90%)."],"dp":[{"h":"Why leishmaniasis targets macrophages","t":"Promastigotes are taken up by macrophages, the very cells meant to kill them, and survive by transforming into amastigotes that resist digestion inside the phagolysosome. They multiply there and spread with these cells to the spleen, liver and bone marrow in visceral disease, which is why marrow puncture finds them and why the spleen enlarges. Source: the lecture's life cycle slides."}]},"parasito-leishmaniasis:e7":{"s":3,"u":["L. tropica: urban, dry, single slow lesion. L. major: rural, wet, multiple, fast.","L. major (zoonotic, rural, 'wet'): short incubation 10-45 days, multiple inflamed crater lesions, heals in under 6 months with a large scar.","Old World localised : L. tropica (anthroponotic, urban, 'dry'): incubation 20 days-7 months, usually a single lesion on exposed skin; papule → central ulcer with crust and inflamed border; painless ; slow (over a year), unsightly scar."],"dp":[{"h":"Why L. tropica and L. major behave differently","t":"L. tropica circulates between humans in towns, producing a single, dry, slow lesion. L. major lives in rural rodents and infects people who enter their habitat; the lesions are multiple and very inflamed but heal faster. Knowing the reservoir explains the setting, the lesion type and the control measures (rodent control vs treating human cases). Source: the lecture's cutaneous leishmaniasis slides."}]},"parasito-leishmaniasis:e8":{"s":3,"u":["Mucocutaneous (L. braziliensis): nose/palate destruction.","Mucocutaneous (espundia, L. braziliensis ) : destruction of nose, palate, pharynx, larynx; death from malnutrition and pneumonia."],"dp":[]},"parasito-leishmaniasis:e10":{"s":4,"u":["VL: antimony 28 days or liposomal amphotericin B.","Visceral : meglumine antimoniate 60 mg/kg/day IM for 28 days; relapse: amphotericin B; liposomal amphotericin B 3 mg/kg/day for 5 days + day 10 (or 10 mg/kg for 2 days).","Others: topical paromomycin ( L. major ), fluconazole, miltefosine, liposomal amphotericin B, thermotherapy (50 °C for 30 s) and cryotherapy ."],"dp":[]},"parasito-leishmaniasis:e11":{"s":4,"u":["Monitor ECG (QT) on antimony.","Monitor antimony toxicity : ECG ( QT prolongation , T and ST changes, arrhythmias), blood counts, liver, pancreas, kidney."],"dp":[]},"parasito-leishmaniasis:e9":{"s":4,"u":["Glucantime: intralesional (< 5 lesions, < 4 cm) or IM 20 mg/kg/d.","Pentavalent antimony (Glucantime, meglumine antimoniate) : intralesional twice weekly for 3-4 weeks (Morocco: under 5 lesions, under 4 cm) or IM 20 mg/kg/day (more than 5 lesions or over 4 cm).","Glucantime contraindications: age over 50, pregnancy, severe renal, hepatic or cardiac failure."],"dp":[]}},"meta":{"1iba1l0":{"a":"recall","vg":"parasito-leishmaniasis:e0/recall/1"},"msiaoc":{"a":"recall","vg":"parasito-leishmaniasis:e2/recall/1"},"aaq6ia":{"a":"recall","vg":"parasito-leishmaniasis:e3/recall/1"},"ti8fxs":{"a":"recall","vg":"parasito-leishmaniasis:e3/recall/1"},"13trzfe":{"a":"recall","vg":"parasito-leishmaniasis:e4/recall/1"},"nxfk34":{"a":"recall","vg":"parasito-leishmaniasis:e5/recall/1"},"1e36y4w":{"a":"recall","vg":"parasito-leishmaniasis:e6/recall/1"},"121v35r":{"a":"recall","vg":"parasito-leishmaniasis:e6/recall/2"},"1ihgpbx":{"a":"recall","vg":"parasito-leishmaniasis:e7/recall/1"},"1jua02y":{"a":"recall","vg":"parasito-leishmaniasis:e7/recall/2"},"1q7sm4e":{"a":"recall","vg":"parasito-leishmaniasis:e7/recall/3"},"wtalfi":{"a":"relationship","vg":"parasito-leishmaniasis:e8/relationship/1"},"1b0t8yg":{"a":"recall","vg":"parasito-leishmaniasis:e9/recall/1"},"bjuawx":{"a":"recall","vg":"parasito-leishmaniasis:e9/recall/2"},"qgn3fk":{"a":"recall","vg":"parasito-leishmaniasis:e9/recall/3"},"1nkkjue":{"a":"recall","vg":"parasito-leishmaniasis:e11/recall/1"},"1ryjd78":{"a":"recall","vg":"parasito-leishmaniasis:e10/recall/1"}},"explRev":"87ea68d9c38f"};
